import java.util.Scanner;

public class OBADef {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long val = sc.nextLong();
        int digits = (int) (Math.log10(Math.abs(val)) + 1);
        System.out.println("" + process(val, digits));
    }

    public static long makeOnes(long count) {
        return (long) (Math.pow(10, count) - 1) / 9;
    }

    public static long process(long n, int len) {
        long ones = makeOnes(len);
        long totalCount = (n / ones) * len;
        n %= ones;
        if (n == 0) return totalCount;
        long option1 = (len + 1) + process(ones - n, len - 1);
        long option2 = process(n, len - 1);
        return totalCount + Math.min(option1, option2);
    }
}
